package EmployeeManagementSystem.controller;
import EmployeeManagementSystem.service.RequestScopeService;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.security.jwt.JwtUtil; import EmployeeManagementSystem.repository.EmployeeRepository; import EmployeeManagementSystem.service.BenefitService;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/benefits") public class BenefitController{
 private final RequestScopeService scope;
 private final BenefitService service; private final JwtUtil jwt; private final EmployeeRepository employees;
 public BenefitController(BenefitService s,JwtUtil j,EmployeeRepository e,RequestScopeService requestScope){this.scope=requestScope;service=s;jwt=j;employees=e;}
 private String tok(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required.");return a.substring(7);} private String user(String a){return jwt.extractUsername(tok(a));} private String role(String a){String r=jwt.extractRole(tok(a));return r==null?"":r.replace("ROLE_","").toUpperCase();} private boolean mgmt(String r){return Set.of("ADMIN","HR").contains(r);}
 @GetMapping("/plans") public List<BenefitPlan> plans(@RequestHeader("Authorization")String a){return service.plans(mgmt(role(a)));}
 @PostMapping("/plans") public BenefitPlan savePlan(@RequestHeader("Authorization")String a,@RequestBody BenefitPlan p){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"HR/Admin access required.");return service.savePlan(p);}
 @DeleteMapping("/plans/{id}") public Map<String,Object> deletePlan(@RequestHeader("Authorization")String a,@PathVariable Long id){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"HR/Admin access required.");try{service.deletePlan(id);return Map.of("success",true);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @GetMapping("/my") public List<BenefitEnrollment> my(@RequestHeader("Authorization")String a){return service.myEnrollments(user(a));}
 @GetMapping("/enrollments") public List<BenefitEnrollment> all(@RequestHeader("Authorization")String a){String r=role(a);if(!mgmt(r)&&!"MANAGER".equals(r))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");return scope.visibleTo(role(a),user(a),service.allEnrollments());}
 @PostMapping("/plans/{id}/enroll") public BenefitEnrollment enroll(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody BenefitEnrollment e){String u=user(a);String n=employees.findByRegisterEmployee_UserId(u).map(x->x.getFullName()).orElse(u);try{return service.enroll(id,e,u,n);}catch(Exception x){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,x.getMessage());}}
 @PutMapping("/enrollments/{id}") public BenefitEnrollment update(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody BenefitEnrollment e){try{return service.update(id,e,user(a));}catch(Exception x){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,x.getMessage());}}
 @PatchMapping("/enrollments/{id}/review") public BenefitEnrollment review(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody Map<String,Object>b){scope.assertCanReviewById(role(a),user(a),service.allEnrollments(),id);if(!Set.of("ADMIN","HR","MANAGER").contains(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");try{return service.review(id,String.valueOf(b.get("status")),String.valueOf(b.getOrDefault("comment","")),user(a));}catch(Exception x){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,x.getMessage());}}
 @PatchMapping("/enrollments/{id}/cancel") public Map<String,Object> cancel(@RequestHeader("Authorization")String a,@PathVariable Long id){try{service.cancel(id,user(a));return Map.of("success",true);}catch(Exception x){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,x.getMessage());}}
}
